// Daily Performance Journal
const portfolio = $('Get Portfolio').first().json;
const trades = $('Get All Trades').first().json;
const status = $('Get Status').first().json;
const ticker = $('Get BTC Price').first().json;

const now = new Date();
const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime() / 1000;
const currentPrice = ticker.tickers?.XXBTZUSD?.price || 0;

// Filter today's trades
const todaysTrades = (trades.trades || []).filter(t => t.time >= todayStart);

// Calculate metrics from all trades
let totalBought = 0, totalSold = 0;
let totalBuyCost = 0, totalSellRevenue = 0;
let totalFees = 0;

for (const trade of trades.trades || []) {
  const volume = parseFloat(trade.volume);
  const cost = parseFloat(trade.cost);
  const fee = parseFloat(trade.fee);
  totalFees += fee;

  if (trade.side === 'buy') {
    totalBought += volume;
    totalBuyCost += cost;
  } else {
    totalSold += volume;
    totalSellRevenue += cost;
  }
}

// Cost basis and P&L
const netBtc = totalBought - totalSold;
const avgCostBasis = totalBought > 0 ? totalBuyCost / totalBought : 0;
const currentBtcValue = netBtc * currentPrice;
const totalInvested = totalBuyCost - totalSellRevenue;
const unrealizedPnl = currentBtcValue - totalInvested;
const unrealizedPnlPct = totalInvested > 0 ? (unrealizedPnl / totalInvested) * 100 : 0;

// Portfolio metrics
const equity = portfolio.portfolio?.equity || 0;
const totalValue = portfolio.portfolio?.total_value_usd || 0;

// Today's activity summary
const todayBuys = todaysTrades.filter(t => t.side === 'buy');
const todaySells = todaysTrades.filter(t => t.side === 'sell');
const todayVolume = todaysTrades.reduce((sum, t) => sum + parseFloat(t.cost), 0);
const todayFees = todaysTrades.reduce((sum, t) => sum + parseFloat(t.fee), 0);

// Journal entry
const journal = {
  date: now.toISOString().split('T')[0],
  timestamp: now.toISOString(),

  summary: {
    total_value_usd: totalValue,
    equity: equity,
    btc_holdings: netBtc,
    btc_price: currentPrice,
    trading_halted: status.trading_halted || false
  },

  todays_activity: {
    trades_count: todaysTrades.length,
    buys: todayBuys.length,
    sells: todaySells.length,
    volume_usd: todayVolume,
    fees_paid: todayFees
  },

  all_time_metrics: {
    total_trades: (trades.trades || []).length,
    total_btc_bought: totalBought,
    total_btc_sold: totalSold,
    net_btc_position: netBtc,
    total_invested_usd: totalInvested,
    total_fees_paid: totalFees,
    avg_cost_basis: avgCostBasis,
    current_btc_price: currentPrice,
    unrealized_pnl_usd: unrealizedPnl,
    unrealized_pnl_pct: unrealizedPnlPct
  },

  health: {
    system_status: status.status || 'unknown',
    uptime: status.uptime || 'unknown',
    kraken_auth: status.health?.kraken_auth || 'unknown',
    consecutive_errors: status.health?.errors || 0
  },

  // Learnings placeholder - future: integrate with Qdrant
  learnings: {
    market_regime: currentPrice > avgCostBasis ? 'favorable' : 'underwater',
    position_health: unrealizedPnlPct > 0 ? 'profitable' : 'losing',
    recommendation: unrealizedPnlPct < -10 ? 'Consider pausing buys' : 
                    unrealizedPnlPct > 10 ? 'Consider taking profits' : 'Continue strategy'
  }
};

return [{ json: journal }];

